changeSet.sql:
ALTER TABLE players ADD CONSTRAINT ck_players_resources CHECK
    (level >= 1 AND experience >= 0 AND gold >= 0 AND max_hp >= 1
     AND current_hp >= 0 AND max_mp >= 0 AND current_mp >= 0 AND stat_points >= 0);
ALTER TABLE players ADD CONSTRAINT ck_players_base_stats CHECK
    (stat_str BETWEEN 1 AND 30 AND stat_dex BETWEEN 1 AND 30 AND stat_con BETWEEN 1 AND 30
     AND stat_int BETWEEN 1 AND 30 AND stat_wis BETWEEN 1 AND 30 AND stat_cha BETWEEN 1 AND 30);
ALTER TABLE player_items ADD CONSTRAINT ck_player_items_values CHECK
    (amount > 0 AND item_xp >= 0 AND tier >= 1 AND durability >= 0);
ALTER TABLE monster_loot_tables ADD CONSTRAINT ck_monster_loot_values CHECK
    (min_amount > 0 AND max_amount >= min_amount AND drop_chance BETWEEN 0 AND 100);
ALTER TABLE location_loot_tables ADD CONSTRAINT ck_location_loot_values CHECK
    (min_amount > 0 AND max_amount >= min_amount AND find_chance BETWEEN 0 AND 100);
ALTER TABLE location_random_encounters ADD CONSTRAINT ck_random_encounter_weight CHECK (spawn_chance > 0);
ALTER TABLE merchant_offers ADD CONSTRAINT ck_merchant_offer_values CHECK
    (unit_price >= 0 AND available_quantity >= -1 AND min_level >= 1);
ALTER TABLE quest_templates ADD CONSTRAINT ck_quest_template_values CHECK
    (target_count > 0 AND reward_xp >= 0 AND reward_gold >= 0
     AND min_level >= 1 AND reward_item_amount >= 0);
ALTER TABLE player_quests ADD CONSTRAINT ck_player_quest_progress CHECK (current_progress >= 0);
ALTER TABLE combat_encounters ADD CONSTRAINT ck_combat_encounter_round CHECK (round >= 1);
ALTER TABLE combat_log_entries ADD CONSTRAINT ck_combat_log_round CHECK (round >= 1);
ALTER TABLE player_location_search_states ADD CONSTRAINT ck_search_attempts CHECK
    (remaining_attempts BETWEEN 0 AND 10);
ALTER TABLE trade_operations ADD CONSTRAINT ck_trade_operation_amount CHECK (amount BETWEEN 1 AND 1000);
ALTER TABLE forge_operations ADD CONSTRAINT ck_forge_operation_values CHECK
    (gained_xp >= 0 AND resulting_xp >= 0 AND resulting_tier >= 1);

rollback.sql:
