ALTER TABLE player_quests DROP CONSTRAINT ck_player_quest_progress;
ALTER TABLE quest_templates DROP CONSTRAINT ck_quest_template_values;
ALTER TABLE merchant_offers DROP CONSTRAINT ck_merchant_offer_values;
ALTER TABLE location_random_encounters DROP CONSTRAINT ck_random_encounter_weight;
ALTER TABLE location_loot_tables DROP CONSTRAINT ck_location_loot_values;
ALTER TABLE monster_loot_tables DROP CONSTRAINT ck_monster_loot_values;
