changeSet.sql:
UPDATE combat_encounters SET active_player_key = player_id WHERE status = 'ACTIVE';
UPDATE player_quests SET active_quest_key = true WHERE status IN ('ACTIVE', 'COMPLETED');
UPDATE player_items SET equipped_slot_key = equipped_slot
 WHERE is_equipped = true AND equipped_slot != 'NONE'

DROP INDEX IF EXISTS uq_active_encounter_player;
DROP INDEX IF EXISTS uq_player_active_quest;
DROP INDEX IF EXISTS uq_player_equipped_slot

rollback.sql:
CREATE UNIQUE INDEX uq_active_encounter_player ON combat_encounters(player_id) WHERE status = 'ACTIVE';
CREATE UNIQUE INDEX uq_player_active_quest ON player_quests(player_id, quest_template_id)
    WHERE status IN ('ACTIVE', 'COMPLETED');
CREATE UNIQUE INDEX uq_player_equipped_slot ON player_items(player_id, equipped_slot)
    WHERE is_equipped = true AND equipped_slot != 'NONE'
